/* ARTEX dashboard/sidebar interaction adaptation; see frontend/NOTICE. */
(()=>{'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={dashboard:'仪表盘',chat:'对话',tasks:'任务',schedules:'计划任务',assets:'资产',llm:'LLM',agents:'Agent',mcp:'MCP',skills:'Skill',tools:'工具',notify:'通知推送',intercept:'拦截规则',approvals:'审批记录',logs:'日志',settings:'系统配置'};
const icons={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',chat:'M21 15a4 4 0 0 1-4 4H7l-4 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4z',tasks:'M9 12l2 2 4-4 M5 3h14v18H5z',schedules:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16',assets:'M12 3l9 5v10l-9 4-9-4V8z M3 8l9 5 9-5 M12 13v9',tools:'M14 6l4 4 4-4a7 7 0 0 1-9 9l-6 6-4-4 6-6a7 7 0 0 1 9-9z',other:'M12 3v3 M12 18v3 M3 12h3 M18 12h3 M6 6l2 2 M16 16l2 2 M6 18l2-2 M16 8l2-2 M8 12a4 4 0 1 0 8 0 4 4 0 1 0-8 0'};
const icon=k=>`<svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[k]||icons.other}"/></svg>`;
const state={token:'',route:'dashboard',seq:0,session:0,detailSeq:0,controllers:new Set(),registry:null,taskCursor:'',taskItems:[],busy:false};
const reasonMap={ACCOUNT_SCOPE_MAPPING_REQUIRED:'尚未配置当前操作员的账号映射',ACCOUNT_SOURCE_UNAVAILABLE:'账号概览服务暂不可用',ACCOUNT_SOURCE_HTTP_ERROR:'账号概览服务返回错误',ACCOUNT_SOURCE_SCHEMA_UNKNOWN:'账号概览格式未验证',HEARTBEAT_STALE_OR_UNKNOWN:'心跳已过期或未知',FRESH_HEARTBEAT:'有效心跳',OFFLINE:'离线',UNKNOWN_STATE:'状态无法确认',DUPLICATE_QQ_INSTANCE:'同一 QQ 存在多个实例，需核对',DUPLICATE_INSTANCE_ID:'实例标识重复',INSTANCE_MISSING:'注册实例未返回',ONLINE_UNKNOWN:'在线状态未知',OVERVIEW_ONLINE:'概览确认在线',OVERVIEW_OFFLINE:'概览确认离线',OVERVIEW_EXPLICIT_ERROR:'概览明确报错',QQ_IDENTITY_UNVERIFIED_OR_MISMATCH:'QQ 身份未核实或不匹配',INSTANCE_SCHEMA_UNKNOWN:'实例字段格式未验证',NO_RECORDED_MODEL_USAGE:'暂无已记录的模型用量'};
const reason=r=>reasonMap[r]||(/INCOMPLETE_USAGE_RECORDS/.test(r)?'模型用量记录不完整':r);
const labels={DRAFT:'草稿',VALIDATING:'校验中',READY:'就绪',RUNNING:'运行中',WAITING_EXTERNAL:'等待外部结果',VERIFYING:'验证中',PAUSING:'暂停中',PAUSED:'已暂停',BLOCKED:'阻塞',RECONCILING:'对账中',CANCELLING:'取消中',CANCELLED:'已取消',COMPLETED:'已完成',SUCCEEDED:'已完成',FAILED:'失败',PARTIAL:'部分完成',EXPIRED:'已过期'};
const empty=(title,note)=>`<div class="empty"><strong>${esc(title)}</strong><small>${esc(note)}</small></div>`;
const card=(title,body,extra='')=>`<section class="card ${extra}"><div class="card-head"><h2>${esc(title)}</h2></div>${body}</section>`;
const fmt=n=>n==null?'—':Number(n).toLocaleString('zh-CN');
function clearDetail(){state.detailSeq++;state.configBusy=false;state.contentBusy=false;if($('#details').open)$('#details').close();$('#detail-title').textContent='';$('#detail-body').replaceChildren()}
function resetSession(){state.session++;state.seq++;state.token='';for(const ctrl of state.controllers)ctrl.abort();state.controllers.clear();clearDetail();state.workSettings=null;state.settingsBusy=false;state.proxyBusy=false;state.registry=null;state.taskItems=[];state.taskCursor='';state.models=[];state.contentItems=[];state.contentCan=false;state.reviewOffset=0;state.reviewDecision='';state.reviewAccount='';state.reviewSend='';state.configItems=[];state.configSkills=[];state.configModels=[];state.configCan=false;state.configOp=(state.configOp||0)+1;state.configBusy=false;state.modelSeq=(state.modelSeq||0)+1;state.busy=false;$('#updated').textContent='';$('#content').replaceChildren();$('#error').textContent='';$('#error').hidden=true;$('#credential').value='';$('#refresh').disabled=false;$('#auth').hidden=false;$('#connection').textContent='尚未连接'}
async function api(path,options={},valid=()=>true){const session=state.session,seq=state.seq,token=state.token,ctrl=new AbortController();state.controllers.add(ctrl);const timer=setTimeout(()=>ctrl.abort(),path==='/v1/operator/system/web-search/test'?12000:8000);try{const res=await fetch(path,{...options,headers:{...(options.headers||{}),Authorization:`Bearer ${token}`,...(options.body?{'Content-Type':'application/json'}:{})},cache:'no-store',redirect:'error',signal:ctrl.signal});if(res.status===401&&session===state.session&&seq===state.seq&&valid()){resetSession();load()}let raw;try{raw=await res.json()}catch{throw Error(`服务响应格式错误（${res.status}）`)}if(!res.ok)throw Error(`${res.status} · ${raw.error?.code||'请求失败'}`);return raw}finally{clearTimeout(timer);state.controllers.delete(ctrl)}}
function nav(){const footer=$('#sidebar footer .dot')?.nextSibling;if(footer&&footer.nodeType===3)footer.textContent=' 配置工作台 · B4';const keys=Object.keys(paths);$('#navigation').innerHTML=[['功能',keys.slice(0,5)],['系统',keys.slice(5)]].map(([group,items])=>`<div class="nav-group">${group}</div>${items.map(k=>`<a href="/product/${k}" data-route="${k}" ${state.route===k?'aria-current="page"':''}>${icon(k)}<span>${paths[k]}</span>${k==='settings'?'<span class="soon">部分接入</span>':!['dashboard','tasks','tools','llm','agents','skills','intercept','approvals','chat','notify'].includes(k)?'<span class="soon">待接入</span>':''}</a>`).join('')}`).join('')}
function route(){clearDetail();state.taskCursor='';state.taskItems=[];$('#updated').textContent='';state.route=location.pathname.split('/')[2]||'dashboard';if(!paths[state.route])state.route='dashboard';$('#title').textContent=state.route==='dashboard'?'总览':paths[state.route];$('#crumb').textContent=paths[state.route];$('#subtitle').textContent=state.route==='dashboard'?'QQ 业务全局状态 · 实时只读投影':state.route==='tasks'?'复用现有任务列表与详情 · 不执行平台操作':state.route==='tools'?'NapCat 原名目录 · 参数与实例支持尚未验证':state.route==='llm'?'模型配置 · 工作空间规划路由':state.route==='agents'?'规划与表达角色 · 模型、技能快照与版本管理':state.route==='skills'?'中文运营流程 · 可编辑草稿与发布版本 · 不授予权限':state.route==='intercept'?'内容规则 · 版本校验与试跑 · 不授予发送权':state.route==='approvals'?'脱敏内容审核证据 · 说明不重发':state.route==='settings'?'工作并发、模型出口与网络搜索 · 按工作空间隔离':state.route==='chat'?'Agent 对话与 QQ 收件箱双视图 · 按 workspace 与账号隔离':state.route==='notify'?'脱敏通知投影 · 本地记录 · CAS 已读':'完整产品范围 · 本批待接入';nav();$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');load()}
const qq03TypeLabels={'group.acquire':'加群任务','group.analyze':'群分析任务','chat':'聊天任务','customer.add_me':'客户加我','customer.add_customer':'我加客户'};
const qq03MatrixRows=[['group.acquire','既有执行链 · 已接线','沿用现有 reserve/permit/bridge 链，旧任务语义未改'],
['group.analyze','执行明确 unsupported','仅识别、持久化与读回；本批只接受 dry_run/read_only；执行依赖现有 Summary/Collector 能力证据，不真实登录或访问群'],
['chat','执行明确 unsupported','任务对象仅识别与读回；日常聊天仍走独立 chat permit 链，不混用'],
['customer.add_me','执行明确 unsupported','无已证实的好友动作 adapter 能力（docs/capabilities/P0-02.md）；不猜测 API、不触发写'],
['customer.add_customer','执行明确 unsupported','同上；未知类型仍被拒绝；提交被明确拒绝（CAPABILITY_UNAVAILABLE），不算执行成功，不自动重发']];
function qq03CreateCard(){return card('任务创建 · 类型支持矩阵',`<div class="table-wrap"><table><thead><tr><th>类型</th><th>能力状态</th><th>边界</th></tr></thead><tbody>${qq03MatrixRows.map(r=>`<tr><td>${esc(qq03TypeLabels[r[0]])} <code>${esc(r[0])}</code></td><td>${esc(r[1])}</td><td>${esc(r[2])}</td></tr>`).join('')}</tbody></table></div><form id="qq03-create-form" class="config-form"><label>类型（创建/读回已接线）<select id="qq03-type">${qq03MatrixRows.map(r=>`<option value="${esc(r[0])}">${esc(qq03TypeLabels[r[0]])} · ${esc(r[1])}</option>`).join('')}</select></label><label>任务名称<input id="qq03-title" required maxlength="200"></label><label>账号标识（当前工作空间）<input id="qq03-account" required maxlength="128"></label><label>目标 QQ 群 / 客户 QQ 标识（十进制）<input id="qq03-target" required inputmode="numeric" maxlength="64"></label><label>来源标识（provenance）<input id="qq03-ref" required maxlength="128"></label><button type="submit">创建草稿（不触发执行）</button><p id="qq03-create-status" role="status"></p><p class="muted">本表单只创建草稿并回读真实类型；无执行链类型的提交会被明确拒绝，未知类型永远拒绝；读取矩阵来自离线决策文档，不代表 live 能力。</p></form>`)}
async function qq03CreateFormAction(e){e.preventDefault();const status=$('#qq03-create-status');const body={type:$('#qq03-type').value,join_reason:"",verification_message:"",title:$('#qq03-title').value.trim(),goal:{metric:"new_unique_groups_for_account_pool",count:1,strict_target_cap:true,require_final_membership_check:true},allowed_account_ids:[$('#qq03-account').value.trim()],candidate_source:{kind:"fixed",groups:[{group_id:$('#qq03-target').value.trim(),source_ref:$('#qq03-ref').value.trim()}]},execution_mode:"dry_run",deadline_at:new Date(Date.now()+3600000).toISOString(),limits:{max_candidates:1,max_attempts_per_action:1,max_total_external_attempts:1,max_model_attempts:0},approval_ref:null,submit:false};status.textContent='正在提交草稿…';try{const raw=await api('/v1/tasks',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(body)});status.textContent='已创建草稿 · 服务端读回真实类型：'+(raw.data.type||'未知');await load()}catch(err){status.textContent='创建失败（未执行任何外部动作）：'+err.message}}
function taskTable(items){if(!items.length)return empty('暂无任务','当前操作员范围内未发现任务，不展示演示数据');return `<div class="table-wrap"><table><thead><tr><th>任务名称</th><th>类型</th><th>状态</th><th>目标进度</th><th>创建时间</th></tr></thead><tbody>${items.map(t=>`<tr><td><button data-task="${esc(t.id)}">${esc(t.title||t.id)}</button></td><td>${esc(qq03TypeLabels[t.type]||t.type)}</td><td><span class="badge ${t.state==='RUNNING'?'blue':t.state==='BLOCKED'?'amber':''}">${esc(labels[t.state]||t.state)}</span></td><td>${fmt(t.confirmed_unique_count)} / ${fmt(t.goal_count)}</td><td>${esc(new Date(t.created_at).toLocaleString('zh-CN'))}</td></tr>`).join('')}</tbody></table></div>`}
function dashboard(d){const a=d.accounts,c=a.counts,t=d.tokens;let accountNote=a.availability==='available'?`<span class="green">在线 ${c.online}</span><span class="muted">离线 ${c.offline}</span><span class="amber">异常 ${c.abnormal}</span>`:esc(reason(a.reason));const stat=(k,title,value,note)=>`<section class="card"><div class="stat-title">${icon(k)}${esc(title)}</div><div class="stat-value">${value}</div><div class="stat-note metrics-inline">${note}</div></section>`;
let chart=empty('暂无可核实的 Token 用量',reason(t.reason)+'；缺失用量不会显示为 0');if(t.availability==='available'){const days=t.daily.slice(-30),max=Math.max(1,...days.flatMap(x=>[x.input,x.output]));chart=`<div class="metrics-inline muted">输入 ${fmt(t.input)} · 输出 ${fmt(t.output)} · 缓存读写未计量</div><div class="chart" role="img" aria-label="按 UTC 日期记录的模型输入输出 Token 图">${days.map(x=>`<div class="chart-group"><svg viewBox="0 0 100 160" width="100%" height="100%" preserveAspectRatio="none" aria-hidden="true"><rect x="6" y="${160-Math.round(x.input/max*150)}" width="38" height="${Math.max(1,Math.round(x.input/max*150))}" fill="#60a5fa"/><rect x="50" y="${160-Math.round(x.output/max*150)}" width="38" height="${Math.max(1,Math.round(x.output/max*150))}" fill="#a78bfa"/></svg><span class="chart-label">${esc(x.date.slice(5))}</span></div>`).join('')}</div><div class="legend"><span class="blue">● 输入</span><span class="violet">● 输出</span><span class="muted">近 30 个有记录日期 · UTC</span></div>`}
$('#content').innerHTML=`<div class="stats">${stat('tasks','活跃任务',fmt(d.tasks.active),`共 ${fmt(d.tasks.total)} 项 · 当前可见任务`)}${stat('chat','QQ 状态',a.total==null?'未知':fmt(a.total),accountNote)}${stat('assets','引流成功客户数','—','待接入客户证据与好友关系；按客户去重')}${stat('other','Token 用量',fmt(t.total),'仅当前操作员规划网关记录')}</div>${card('Token 用量趋势',chart,'chart-card')}${card('任务概览',taskTable(d.tasks.recent)+'<a class="blue" href="/product/tasks" data-route="tasks">查看全部任务 →</a>','table-card')}<div class="bottom-grid">${card('资产分布',empty('客户资产后端待接入','按客户状态 / 来源统计；未配置意向规则，不自动入库'))}${card('系统状态',`<div class="system-row"><span>任务数据库</span><span class="green">已连接</span></div><div class="system-row"><span>账号来源</span><span>${a.source==='local6300'?'固定本机概览':'账户心跳投影'}</span></div><div class="system-row"><span>QQ 事件接入</span><span class="amber">未知 · 无作用域健康源</span></div><div class="system-row"><span>意向识别规则</span><span>未配置 · 未启用</span></div><div class="system-row"><span>工具执行</span><span>本批仅注册目录</span></div>`)}</div>${card('QQ 账号实例',a.availability==='available'?(a.instances.length?`<div class="table-wrap"><table><thead><tr><th>实例 / 账号</th><th>QQ</th><th>状态</th><th>说明</th></tr></thead><tbody>${a.instances.map(x=>`<tr><td>${esc(x.instance_id)}<br><small class="muted">${esc(x.id)}</small></td><td>${esc(x.self_id||'未核实')}</td><td>${{online:'在线',offline:'离线',abnormal:'异常'}[x.status]||'异常'}</td><td>${esc(reason(x.reason))}</td></tr>`).join('')}</tbody></table></div><p class="muted">实例互斥计数；已知 QQ 去重 ${a.unique_known_accounts}，冲突实例 ${a.conflict_instances}。无缓存，状态时效 90 秒。</p>`:empty('暂无注册实例','未注册账号不计为离线')):empty('账号概览不可用',reason(a.reason)),'table-card')}`;$('#updated').textContent=`更新时间 ${new Date(d.generated_at).toLocaleString('zh-CN')} · 缓存 ${d.cache_age_seconds} 秒 · 工作空间 ${d.scope.workspace_id}`;
}
const pendingText={chat:['Agent 流式输出、停止与可追溯工具结果','收件箱已有真实读取；实时刷新与自动分诊待接入'],schedules:['持久计划、时区、下次执行与运行历史','触发现有任务引擎；重启补偿、重叠与幂等实测'],assets:['客户 QQ 唯一、意向证据、来源与规则版本','意向 + 至少一个运营 QQ 好友关系才算引流成功','规则配置 / 预览 / 启用 / 历史；当前无认可规则，未启用'],llm:['配置持久化、密钥遮罩、连接测试与默认路由','并发 / 预算 / 超时运行时有效，不仅是表单'],agents:['主 Agent 规划 / 确定性调度 / Character 表达分工','模型、工具、Skill 绑定与版本'],mcp:['MCP 连接与 ChatLuna / Character / 群分析 Koishi 插件分开','仓库 URL 不等于 MCP endpoint；只封装受限 BBA API'],skills:['群规识别、群分析、意向识别、接待问答、合意联系方式跟进、任务复盘','中文可编辑流程、版本、依赖、停止条件；Skill 不授予权限'],notify:['事件订阅规则与失败重试 · 投递仅本地记录'],intercept:['关键词 / 模式 / 规则分组 / 启禁 / 优先级 / 试跑 / 版本','所有最终出站 payload 统一校验；媒体未覆盖不能默默放行'],approvals:['审批聚焦出站内容审核，不新增普通动作逐条审批','旧任务授权契约保留；后续独立策略接入与迁移'],logs:['运行 / 任务 / 工具 / 模型 / 内容审核日志','关联 ID、筛选分页、脱敏与保留期限'],settings:['代理 / 网络搜索 / Work Agent 并发运行时消费','账号会话 / 时区 / 预算 / 频率 / 备份 / 紧急暂停 / 权限','不更改现有 QQ 登录与 ARTEX 部署']};
function pending(){const k=state.route;$('#content').innerHTML=`${k==='chat'?'<div class="tabs" role="tablist"><button role="tab" aria-selected="true" data-tab="Agent">Agent 对话</button><button role="tab" aria-selected="false" data-tab="QQ">QQ 收件箱</button></div>':''}<section class="card pending"><span class="badge">待接入 · 不计为已完成</span><h2 id="pending-title">${esc(paths[k])} · 下一批真实后端接入</h2><p>本页保留完整产品验收范围。本批未实现此模块的配置或业务执行，不提供假数据操作。</p><ul>${(pendingText[k]||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`}
async function loadModels(seq){const session=state.session;$('#refresh').disabled=false;$('#content').innerHTML='<div class="loading">正在读取模型配置…</div>';try{const raw=await api('/v1/operator/models');if(session!==state.session||seq!==state.seq||state.route!=='llm')return;state.models=raw.data.items;state.canConfigure=raw.data.can_configure;renderModels();$('#connection').textContent='已认证 · 模型配置';$('#updated').textContent='规划路由：工作空间默认模型 · 无配置时兼容启动配置'}catch(e){if(session!==state.session||seq!==state.seq||state.route!=='llm')return;$('#content').innerHTML=empty('模型配置不可用','需要服务显式启用保护文件注册表；不会伪造配置');$('#error').textContent='读取失败：'+e.message;$('#error').hidden=false}}
function renderModels(){const controls=p=>state.canConfigure?`<div class="toolbar"><button data-model-edit="${esc(p.id)}">编辑</button><button data-model-test="${esc(p.id)}">连接测试</button><button data-model-default="${esc(p.id)}" ${p.is_default?'disabled':''}>设为默认</button><button data-model-toggle="${esc(p.id)}" ${p.is_default?'disabled title="请先切换默认模型"':''}>${p.enabled?'禁用':'启用'}</button><button data-model-delete="${esc(p.id)}" ${p.is_default?'disabled title="请先切换默认模型"':''}>删除</button></div>`:'';$('#content').innerHTML=card('模型配置',`<p>复用 BBA OpenAI 兼容规划网关；单次非流式调用，仅生成澄清，不授予工具权限。默认模型按工作空间隔离；默认配置不可直接禁用、清密钥或删除，请先切换默认。</p>${state.canConfigure?'<button id="model-new">创建模型</button>':'<span class="badge">只读权限 · 无配置写权限</span>'}<div id="model-message" role="status"></div>`)+`<div class="tool-grid">${state.models.map(p=>card(p.name,`<p>${esc(p.model)} · ${p.enabled?'启用':'禁用'} ${p.is_default?'· 规划默认':''}</p><p>${esc(p.base_url)}</p><p>密钥：${p.has_secret?'已安全保管':'未配置'} · 超时 ${p.timeout_seconds}s · 并发 ${p.max_concurrent} · 版本 ${p.version}</p>${controls(p)}`)).join('')||empty('暂无模型配置','不会自动调用付费模型')}</div>`}
function modelForm(id=''){clearDetail();const p=state.models.find(x=>x.id===id)||{id:'',name:'',model:'',base_url:'',enabled:true,is_default:false,timeout_seconds:10,max_concurrent:1,version:0};state.editModel=p.id;$('#detail-title').textContent=p.id?'编辑模型':'创建模型';$('#detail-body').innerHTML=`<form id="model-form" class="model-form"><label>名称<input name="name" required maxlength="100" value="${esc(p.name)}"></label><label>模型标识<input name="model" required maxlength="200" value="${esc(p.model)}"></label><label>Base URL（以 /v1 结尾）<input name="base_url" required value="${esc(p.base_url)}"></label><label>超时秒数<input name="timeout_seconds" type="number" min="1" max="120" value="${p.timeout_seconds}"></label><label>最大并发<input name="max_concurrent" type="number" min="1" max="32" value="${p.max_concurrent}"></label><label><input name="enabled" type="checkbox" ${p.enabled?'checked':''}>启用</label><label><input name="is_default" type="checkbox" ${p.is_default?'checked':''}>规划默认</label><label>密钥操作<select name="secret_action"><option value="keep">保留现有密钥</option><option value="replace">替换密钥</option><option value="clear">明确清除密钥</option></select></label><label>新密钥（仅替换时提交）<input name="api_key" type="password" autocomplete="new-password" value=""></label><p>密钥不回显、不存浏览器存储。私网 HTTP 需要部署侧精确授权，页面不能自行放开。</p><button type="submit">保存配置</button><div id="model-form-error" role="alert"></div></form>`;$('#details').showModal();$('#model-form').onsubmit=async e=>{e.preventDefault();const f=e.target,d=new FormData(f),body={name:d.get('name'),model:d.get('model'),base_url:d.get('base_url'),timeout_seconds:Number(d.get('timeout_seconds')),max_concurrent:Number(d.get('max_concurrent')),enabled:d.has('enabled'),is_default:d.has('is_default'),expected_version:p.version,secret_action:d.get('secret_action')};if(body.secret_action==='replace')body.api_key=d.get('api_key');f.elements.api_key.value='';await modelAction(p.id,p.id?'PUT':'POST',body,true)}}
async function modelAction(id,method,body,form=false,test=false){const session=state.session,seq=state.seq,detailSeq=state.detailSeq,op=(state.modelSeq||0)+1;state.modelSeq=op;const current=()=>session===state.session&&seq===state.seq&&state.route==='llm'&&state.modelSeq===op&&(!form||detailSeq===state.detailSeq);try{await api('/v1/operator/models'+(id?'/'+encodeURIComponent(id):'')+(test?'/test':''),{method,...(body?{body:JSON.stringify(body)}:{})},current);if(!current())return;if(test){$('#model-message').textContent='连接成功 · 同一模型适配器实测';return}if(form)clearDetail();await load()}catch(e){if(!current())return;const target=form?$('#model-form-error'):$('#model-message');if(target)target.textContent='操作失败：'+e.message+'；版本冲突请刷新重试，当前配置未覆盖'}}
document.addEventListener('click',e=>{if(e.target.id==='model-new')modelForm();for(const action of ['edit','test','default','toggle','delete']){const el=e.target.closest('[data-model-'+action+']');if(!el)continue;const id=el.getAttribute('data-model-'+action),p=state.models.find(x=>x.id===id);if(!p)return;if(action==='edit'){modelForm(id);return}if(action==='test'){modelAction(id,'POST',null,false,true);return}if(action==='delete'){modelAction(id,'DELETE',{expected_version:p.version});return}const {id:unused,version,has_secret,...fields}=p;modelAction(id,'PUT',{...fields,enabled:action==='toggle'?!p.enabled:p.enabled,is_default:action==='default'?true:p.is_default,expected_version:version,secret_action:'keep'})}});

// B2: ARTEX card/editor hierarchy adapted to BBA's versioned configuration API.
const configNames={agents:'Agent',skills:'Skill'};
const skillFields=[['inputs','输入'],['steps','执行步骤'],['required_capabilities','所需能力'],['outputs','输出'],['stop_conditions','停止条件'],['constraints','约束']];
const skillTemplates=[
 {name:'群规识别',description:'从已授权材料提取群规与运营边界',goal:'输出可追溯的群规摘要，不执行群操作',inputs:['用户提供的群规文本','已授权的上下文'],steps:['识别公告中的禁止事项、频率和联系方式约束','逐条标注原文证据与不确定项','生成待人工确认的运营边界'],outputs:['群规摘要及证据'],stop_conditions:['来源缺失或群规相互冲突','需要未经授权读取群消息'],constraints:['不猜测群规','不发送消息、不修改群设置']},
 {name:'群分析',description:'依据已有材料分析话题与需求',goal:'形成带证据的群话题分析草稿',inputs:['用户提供且允许分析的去标识化群材料'],steps:['按主题整理材料','区分明确表达与推测','列出趋势、样本限制与待确认问题'],outputs:['话题分布与需求线索草稿'],stop_conditions:['材料不足或含未授权敏感信息'],constraints:['不批量抓取群消息','不以画像代替用户明确意愿']},
 {name:'意向识别',description:'只识别明确表达并保留来源证据',goal:'提出待确认的意向候选，不自动入库',inputs:['合规提供的对话片段','人工认可的意向规则'],steps:['核对规则版本与适用范围','提取明确需求及对应原文','标记否定、拒绝和无法判定项'],outputs:['意向候选、证据及不确定性'],stop_conditions:['意向规则未配置或未经认可','出现拒绝或证据不足'],constraints:['不将群成员等同客户','不自动标记引流成功或写入资产']},
 {name:'接待问答',description:'依据获准知识准备问答草稿',goal:'提供有依据、可审核的中文回复草稿',inputs:['用户问题','经审核的业务知识'],steps:['核对问题与知识来源','明确已知信息及未知部分','拟定简明回复并标记需人工确认的承诺'],outputs:['回复草稿与依据'],stop_conditions:['涉及价格承诺但无批准依据','知识缺失或对方拒绝沟通'],constraints:['不虚构承诺','仅生成草稿，不发QQ']},
 {name:'合意联系方式跟进',description:'仅在对方明确同意时整理跟进建议',goal:'根据合意证据生成待审核跟进草稿',inputs:['对方明确同意的证据','允许使用的联系方式及跟进范围'],steps:['核对同意对象、范围和有效性','确认未撤回或拒绝','拟定一次克制的跟进草稿'],outputs:['合意依据与跟进草稿'],stop_conditions:['无明确同意或已撤回','联系方式来源无法验证'],constraints:['不诱导索取隐私','不自动添加好友或发送消息']},
 {name:'任务复盘',description:'依据可验证结果复盘，不将未知当成功',goal:'产出事实、阻塞和改进建议',inputs:['任务记录','已确认的执行结果及错误'],steps:['区分成功、失败、未知和等待外部结果','核对目标与证据','整理根因、风险及改进建议'],outputs:['任务复盘报告及证据索引'],stop_conditions:['缺少关键结果证据'],constraints:['不编造成功数量','不自行重试外部动作']}
];
function configCurrent(session,seq,kind,detailSeq){return session===state.session&&seq===state.seq&&state.route===kind&&(detailSeq===undefined||detailSeq===state.detailSeq&&$('#details').open)}
async function loadConfig(seq){const session=state.session,kind=state.route;state.configOp=(state.configOp||0)+1;state.configBusy=false;state.configCan=false;state.configItems=[];state.configSkills=[];state.configModels=[];$('#refresh').disabled=false;$('#content').innerHTML='<div class="loading">正在读取'+configNames[kind]+'配置…</div>';try{const raw=await api('/v1/operator/'+kind,{},()=>configCurrent(session,seq,kind));if(!configCurrent(session,seq,kind))return;state.configItems=raw.data.items;state.configCan=raw.data.can_configure===true;renderConfig();$('#connection').textContent=state.configCan?'已认证 · 配置管理':'已认证 · 只读权限';$('#updated').textContent='配置按工作空间隔离 · 保存使用版本校验 · 不触发QQ操作'}catch(e){if(!configCurrent(session,seq,kind))return;$('#content').innerHTML=empty(configNames[kind]+'配置不可用','请刷新重试；未将读取失败当作空清单');$('#error').textContent='读取失败：'+e.message;$('#error').hidden=false}}
function renderConfig(){const kind=state.route,name=configNames[kind],items=state.configItems;
$('#content').innerHTML=card(name+' 配置',`<div class="config-heading"><div><p>${kind==='agents'?'角色负责规划或表达，调度与工具执行仍由确定性后端负责。':'Skill 是中文运营流程，不是工具权限；发布与启用分别管理。'}</p><p>当前无已验证可执行工具，仅允许空工具绑定。保存配置不会发送QQ消息。</p></div>${state.configCan?`<button id="config-new" class="primary">新建 ${name}</button>`:'<span class="badge">只读权限 · 无配置写权限</span>'}</div><div id="config-message" role="status" aria-live="polite"></div>`)+
`<div class="config-overview"><span>共 ${items.length} 个</span><span>已启用 ${items.filter(x=>x.enabled).length} 个</span>${kind==='skills'?`<span>已发布 ${items.filter(x=>x.published).length} 个</span>`:''}</div><div class="config-grid">${items.map(p=>`<section class="card config-card" data-config-card="${esc(p.id)}"><div class="config-card-title">${icon(kind)}<h2>${esc(p.name)}</h2><span class="badge ${p.enabled?'blue':''}">${p.enabled?'已启用':'已停用'}</span></div><p class="config-description">${esc(p.description||'暂无描述')}</p><div class="config-meta"><span>版本 v${esc(p.version)}</span>${kind==='agents'?`<span>网络搜索 ${p.web_search===true?'偏好开启':'偏好关闭'}</span><span>技能 ${(p.skills||[]).length}</span><span>工具 ${(p.tools||[]).length}</span>`:`<span>${p.published?'已发布':'草稿'}</span><span>步骤 ${(p.steps||[]).length}</span>`}</div><p class="config-id">${esc(p.id)}</p><div class="config-actions"><button data-config-view="${esc(p.id)}">${state.configCan?'编辑配置':'查看配置'}</button><button data-config-history="${esc(p.id)}">版本历史</button>${state.configCan?`<button data-config-toggle="${esc(p.id)}">${p.enabled?'禁用':'启用'}</button><button data-config-delete="${esc(p.id)}" class="danger">删除</button>`:''}</div></section>`).join('')}</div>${items.length?'':empty('暂无 '+name,'新建配置或使用建议模板；不展示伪造业务数据')}`+
(kind==='skills'?card('中文建议模板',`<p>六个模板仅填入本地草稿，保存后才创建；默认未发布、未启用，不包含QQ发送能力。</p><div class="template-grid">${skillTemplates.map((t,i)=>`<button data-skill-template="${i}" ${state.configCan?'':'disabled'}><strong>${esc(t.name)}</strong><small>${esc(t.description)}</small><span>使用草稿 →</span></button>`).join('')}</div>`):'');}
function configBody(p){const {id,version,updated_by,updated_at,...fields}=p;return {...fields,...(state.route==='agents'?{web_search:p.web_search===true}:{}),tools:[],expected_version:version||0}}
function configField(label,name,value,area=false){return `<label>${esc(label)}${area?`<textarea name="${name}" rows="${name==='system_prompt'?7:3}">${esc(Array.isArray(value)?value.map(x=>typeof x==='string'?x:JSON.stringify(x)).join('\n'):value)}</textarea>`:`<input name="${name}" value="${esc(value)}" ${name==='name'?'required maxlength="100"':''}>`}</label>`}
async function configForm(id='',template=null){const kind=state.route,can=state.configCan,p=state.configItems.find(x=>x.id===id)||{id:'',version:0,name:'',description:'',system_prompt:'',model_id:'',skills:[],tools:[],enabled:false,web_search:false,published:false,goal:'',...Object.fromEntries(skillFields.map(([k])=>[k,[]])),...(template||{})};clearDetail();const session=state.session,seq=state.seq,detailSeq=state.detailSeq,current=()=>configCurrent(session,seq,kind,detailSeq);$('#detail-title').textContent=(can?(p.id?'编辑 ':'新建 '):'查看 ')+configNames[kind];$('#detail-body').textContent='正在读取配置依赖…';$('#details').showModal();let models=[],skills=[],versions=new Map();try{if(kind==='agents'){const [m,s]=await Promise.all([api('/v1/operator/models',{},current),api('/v1/operator/skills',{},current)]);if(!current())return;models=m.data.items;skills=s.data.items;const history=await Promise.all(skills.filter(x=>x.enabled).map(async x=>({id:x.id,items:(await api('/v1/operator/skills/'+encodeURIComponent(x.id)+'/history',{},current)).data.items})));if(!current())return;history.forEach(x=>versions.set(x.id,x.items.filter(v=>v.published&&v.enabled)));state.configModels=models;state.configSkills=skills;}}catch(e){if(current())$('#detail-body').innerHTML=`<p role="alert">依赖读取失败：${esc(e.message)}。为避免丢失绑定，本次不能保存。请关闭后重试。</p>`;return}if(!current())return;
const bindingSkills=[...skills];for(const b of p.skills||[])if(!bindingSkills.some(x=>x.id===b.id))bindingSkills.push({id:b.id,name:b.id,enabled:false});
const bindingHTML=bindingSkills.map((sk,i)=>{const bound=(p.skills||[]).find(x=>x.id===sk.id),opts=[...(versions.get(sk.id)||[])];if(sk.enabled&&sk.published&&!opts.some(v=>v.version===sk.version))opts.push(sk);if(bound&&!opts.some(v=>v.version===bound.version))opts.push({version:bound.version,unavailable:true});return `<div class="skill-binding"><label><input type="checkbox" name="skill_${i}" ${bound?'checked':''} ${!sk.enabled&&!bound?'disabled':''}>${esc(sk.name)}${sk.enabled?'':'（当前已停用 / 不可新绑定）'}</label><select name="skill_version_${i}" aria-label="${esc(sk.name)}绑定版本" ${!opts.length?'disabled':''}>${opts.map(v=>`<option value="${esc(v.version)}" ${bound?.version===v.version?'selected':''}>v${esc(v.version)} · ${v.unavailable?'原绑定，当前不可用':'已发布且启用的快照'}</option>`).join('')}</select></div>`}).join('');
$('#detail-body').innerHTML=`<form id="config-form" class="config-form"><fieldset ${can?'':'disabled'}>${configField('名称','name',p.name)}${configField('描述','description',p.description,true)}${kind==='agents'?`<section class="config-section"><h3>配置与提示词</h3><label class="check-label"><input type="checkbox" name="web_search" ${p.web_search===true?'checked':''}>允许此 Agent 使用网络搜索（默认关闭）</label><p>仅保存 Agent 偏好，不授予消费权限；仍受系统总开关、已保存提供方与 model.request / operator.read 权限约束。总开关关闭不会抹除此偏好。</p><label>模型绑定<select name="model_id" required><option value="" disabled>请选择明确模型（不回退默认）</option>${models.map(m=>`<option value="${esc(m.id)}" ${(p.model_id===m.id||(!p.model_id&&m.id===models.find(x=>x.enabled&&x.has_secret)?.id))?'selected':''} ${!m.enabled&&p.model_id!==m.id?'disabled':''}>${esc(m.name)}${m.enabled?'':'（已禁用）'}</option>`).join('')}${p.model_id&&!models.some(x=>x.id===p.model_id)?`<option selected value="${esc(p.model_id)}">原模型（当前不可用）</option>`:''}</select></label>${configField('系统提示词','system_prompt',p.system_prompt,true)}</section><section class="config-section"><h3>Skill 快照绑定</h3><p>仅可新绑定当前启用的技能，且快照须已发布、已启用。版本固定，不自动追随修改。</p>${bindingHTML||'<p>暂无可绑定技能。请先创建、发布并启用 Skill。</p>'}</section>`:`<section class="config-section"><h3>运营流程</h3>${configField('目标','goal',p.goal,true)}${skillFields.map(([key,label])=>configField(label+'（每行一项）',key,p[key]||[],true)).join('')}<p>所需能力当前仅支持 structured_output；其他能力会校验失败。</p><label class="check-label"><input name="published" type="checkbox" ${p.published?'checked':''}>发布此版本（独立于启用状态）</label></section>`}<section class="config-section"><h3>工具与运行边界</h3><p>当前可执行工具：0。工具目录不等于执行授权，工具绑定保持为空。</p><label class="check-label"><input name="enabled" type="checkbox" ${p.enabled?'checked':''}>启用配置（不会触发执行或QQ发送）</label></section></fieldset><p>当前${p.id?'版本 v'+esc(p.version):'为未保存草稿'}${p.updated_by?' · 更新人 '+esc(p.updated_by):''}${p.updated_at?' · '+esc(p.updated_at):''}</p>${can?'<button type="submit" class="primary">保存配置</button>':'<span class="badge">只读查看 · 无法保存</span>'}<div id="config-form-error" role="alert"></div></form>`;
$('#config-form').onsubmit=e=>{e.preventDefault();if(!can||!current()||state.configBusy)return;const f=e.target,d=new FormData(f),body={name:d.get('name').trim(),description:d.get('description').trim(),tools:[],enabled:d.has('enabled'),expected_version:p.version||0};if(kind==='agents'){body.web_search=d.has('web_search');body.system_prompt=d.get('system_prompt');body.model_id=d.get('model_id');body.skills=bindingSkills.flatMap((sk,i)=>d.has('skill_'+i)?[{id:sk.id,version:Number(d.get('skill_version_'+i))}]:[])}else{body.goal=d.get('goal').trim();body.published=d.has('published');for(const [key] of skillFields)body[key]=String(d.get(key)||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean)}configAction(p.id,p.id?'PUT':'POST',body,true)};}
async function configAction(id,method,body,form=false){if(!state.configCan||state.configBusy)return;const session=state.session,seq=state.seq,kind=state.route,detailSeq=state.detailSeq,op=(state.configOp||0)+1;state.configOp=op;state.configBusy=true;const current=()=>configCurrent(session,seq,kind,detailSeq)&&op===state.configOp;const controls=[...document.querySelectorAll('#config-form button[type=submit],#config-confirm-delete')];controls.forEach(x=>x.disabled=true);try{await api('/v1/operator/'+kind+(id?'/'+encodeURIComponent(id):''),{method,body:JSON.stringify(body)},current);if(!current())return;state.configBusy=false;clearDetail();await load()}catch(e){if(!current())return;const target=form?$('#config-form-error'):$('#config-delete-error');if(target)target.textContent='操作失败：'+e.message+'。版本冲突请刷新后重试；权限或依赖不满足时不会覆盖配置。'}finally{if(current()){state.configBusy=false;controls.forEach(x=>x.disabled=false)}}}
async function configHistory(id){const kind=state.route,p=state.configItems.find(x=>x.id===id);if(!p)return;clearDetail();const session=state.session,seq=state.seq,ds=state.detailSeq,current=()=>configCurrent(session,seq,kind,ds);$('#detail-title').textContent=p.name+' · 版本历史';$('#detail-body').textContent='正在读取版本历史…';$('#details').showModal();try{const raw=await api('/v1/operator/'+kind+'/'+encodeURIComponent(id)+'/history',{},current);if(!current())return;$('#detail-body').innerHTML='<p>历史快照只读，不提供回滚或覆盖当前配置。</p><div class="config-history">'+(raw.data.items.map(v=>`<details><summary>版本 v${esc(v.version)} · ${esc(v.updated_by||'未知更新人')} · ${esc(v.updated_at||'时间未知')}</summary><pre>${esc(JSON.stringify(v,null,2))}</pre></details>`).join('')||empty('暂无历史','尚无可用版本记录'))+'</div>'}catch(e){if(current())$('#detail-body').textContent='历史读取失败：'+e.message}}
function configConfirm(id,action){const kind=state.route,p=state.configItems.find(x=>x.id===id);if(!p||!state.configCan||state.configBusy)return;clearDetail();state.configBusy=false;$('#detail-title').textContent=(action==='delete'?'删除':p.enabled?'禁用':'启用')+' '+p.name;$('#detail-body').innerHTML=`<p>${action==='delete'?'删除当前配置；绑定依赖存在时后端会拒绝。历史是否保留以服务契约为准。':'只改变配置启用状态，不触发任何任务或QQ发送。'}此操作将校验版本 v${esc(p.version)}。</p><div class="config-actions"><button id="config-cancel">取消</button><button id="config-confirm-delete" class="${action==='delete'?'danger':'primary'}">确认${action==='delete'?'删除':p.enabled?'禁用':'启用'}</button></div><p id="config-delete-error" role="alert"></p>`;$('#details').showModal();$('#config-cancel').onclick=clearDetail;$('#config-confirm-delete').onclick=()=>configAction(id,action==='delete'?'DELETE':'PUT',action==='delete'?{expected_version:p.version}:{...configBody(p),enabled:!p.enabled});}
document.addEventListener('click',e=>{if(e.target.closest('#config-new')&&state.configCan){configForm();return}const t=e.target.closest('[data-skill-template]');if(t&&state.configCan&&state.route==='skills'){configForm('',{...skillTemplates[Number(t.dataset.skillTemplate)],required_capabilities:['structured_output'],tools:[],published:false,enabled:false});return}for(const action of ['view','history','toggle','delete']){const el=e.target.closest('[data-config-'+action+']');if(!el||!['agents','skills'].includes(state.route))continue;const id=el.getAttribute('data-config-'+action);if(action==='view')configForm(id);else if(action==='history')configHistory(id);else configConfirm(id,action);return}});


// B4-3: persistent workspace defaults; never task live concurrency or execution authority.
const workSettingsPath='/v1/operator/system/work-slots';
function settingsCurrent(session,seq){return session===state.session&&seq===state.seq&&state.route==='settings'&&!!state.token}
function settingsPending(){return proxyPanel()+searchPanel()+card('系统配置完整范围','<p>已接入工作并发、模型出口与网络搜索配置；不代表系统配置全部完成。</p><ul>'+pendingText.settings.map(x=>'<li>'+esc(x)+'</li>').join('')+'<li>日志保留、账号会话管理、时区、预算与频率、紧急暂停 / 恢复、备份与权限继续保留验收要求。</li></ul>')}
function renderWorkSettings(p,session,seq,message=''){
 const current=()=>settingsCurrent(session,seq);state.workSettings=p;state.settingsBusy=false;
 $('#content').innerHTML=card('工作并发 · Work Agent 数',`<div class="config-heading"><p>工作空间 <code>${esc(p.workspace_id)}</code> · 当前版本 <strong id="work-version">v${esc(p.version)}</strong></p><span class="badge ${p.can_configure?'blue':''}">${p.can_configure?'可管理默认':'只读权限'}</span></div><p>每个任务的 proposal work_item 槽数，不是模型请求并发、BatchSize、QQ 实例或进程数；并非通用模型 Agent。</p><form id="work-settings-form" class="config-form"><label>工作空间默认槽数（1–8）<input id="work-slots" name="work_slots" type="number" min="1" max="8" step="1" required value="${esc(p.work_slots)}" ${p.can_configure?'':'disabled'}></label><p id="work-source">${p.source==='workspace'?'已保存 workspace 默认优先于 CLI 后备':'尚无 workspace 配置 · 使用 CLI -task-work-slots 后备'} · BBA 兼容默认 1；不同于 ARTEX 默认 3，是为维持确定性 QQ 执行链原有串行行为，不自动提高执行强度。上限 8 为现有每任务有界槽位上限。</p><button id="work-save" class="primary" type="submit" ${p.can_configure?'':'disabled'}>保存工作空间默认</button><p id="work-settings-message" role="status">${esc(message||(!p.can_configure?'只读：缺少 system.configure，API 同样拒绝修改。':''))}</p></form><h3>仅之后首次启动的任务生效</h3><p>首次启动在同一数据库事务读取并固化；保存与启动按事务锁取得顺序生效。已运行任务、暂停 / 恢复和服务重启均保留原槽数；任务详情显示其固化值，不以此默认替代。</p><p>保存不是启动 worker / proposal，也不授予 external 写权限。读取持久配置失败时首次启动拒绝，不暗中回退。</p><h3>当前服务实际状态（不是所有任务的实际并发）</h3><div id="work-runtime"><div class="system-row"><span>Worker</span><strong>${p.worker_enabled?'已启用':'未启用'}</strong></div><div class="system-row"><span>Proposal 消费</span><strong>${p.proposal_enabled?'已启用':'未启用'}</strong></div><div class="system-row"><span>当前 Transport</span><code>${esc(p.transport)}</code></div></div><p>槽数为上限，不承诺同时达到 N；可用工作、账号容量、业务授权、DB 池和租约等限制仍有效。</p>`)+settingsPending();
 $('#connection').textContent='已认证 · 工作并发'+(p.can_configure?'管理':'只读');$('#updated').textContent='仅当前 workspace · 版本 v'+p.version+' · 非运行任务统一值';
 $('#work-settings-form').onsubmit=async e=>{e.preventDefault();if(!current()||!p.can_configure||state.settingsBusy)return;const n=Number(new FormData(e.target).get('work_slots'));if(!Number.isInteger(n)||n<1||n>8){$('#work-settings-message').textContent='请输入 1–8 的整数';return}state.settingsBusy=true;const button=$('#work-save');button.disabled=true;$('#work-settings-message').textContent='正在保存并读取持久结果…';try{await api(workSettingsPath,{method:'PUT',body:JSON.stringify({work_slots:n,expected_version:p.version})},current);if(!current())return;const saved=await api(workSettingsPath,{},current);if(!current())return;renderWorkSettings(saved.data,session,seq,'保存成功 · 已重新读取持久默认。仅之后首次启动生效。')}catch(err){if(!current())return;$('#work-settings-message').textContent='保存失败：'+err.message+'。未确认保存；409 表示版本冲突，请刷新后核对再提交，不自动覆盖。'}finally{if(current()){await Promise.all([loadProxySettings(session,seq),loadSearchSettings(session,seq)]);state.settingsBusy=false;const b=$('#work-save');if(b)b.disabled=!p.can_configure}}};
}
async function loadWorkSettings(seq){const session=state.session,current=()=>settingsCurrent(session,seq);state.workSettings=null;state.settingsBusy=false;state.proxyBusy=false;$('#refresh').disabled=false;$('#content').innerHTML=card('工作并发 · Work Agent 数','<p>正在读取已认证 workspace 持久默认与服务状态…</p>')+settingsPending();try{const raw=await api(workSettingsPath,{},current);if(!current())return;renderWorkSettings(raw.data,session,seq);await Promise.all([loadProxySettings(session,seq),loadSearchSettings(session,seq)])}catch(e){if(!current())return;$('#content').innerHTML=card('工作并发 · 读取不可用','<p role="alert">读取失败：'+esc(e.message)+'。未显示后备值冒充有效配置，当前无法保存；请检查权限 / 服务后刷新。</p>')+settingsPending();$('#connection').textContent='工作并发配置不可用';$('#updated').textContent='无有效默认 / 版本快照';await Promise.all([loadProxySettings(session,seq),loadSearchSettings(session,seq)])}}

// B6: independent saved search configuration; panel identity also guards same-seq re-renders.
const searchSettingsPath='/v1/operator/system/web-search';
function searchPanel(){return '<div id="search-panel">'+card('网络搜索','<p>正在读取当前工作空间配置…</p>')+'</div>'}
async function loadSearchSettings(session,seq){const panel=$('#search-panel'),current=()=>settingsCurrent(session,seq)&&panel===$('#search-panel');if(!current()||!panel)return;try{const raw=await api(searchSettingsPath,{},current);if(current())renderSearchSettings(raw.data,session,seq)}catch(e){if(current())panel.innerHTML=card('网络搜索 · 不可用','<p role="alert">读取失败：'+esc(e.message)+'。不以空配置冒充读取成功，请检查 system.read 权限或服务状态后刷新。</p>')}}
function renderSearchSettings(p,session,seq,message=''){
 const panel=$('#search-panel');if(!settingsCurrent(session,seq)||!panel)return;
 const current=()=>settingsCurrent(session,seq)&&panel===$('#search-panel')&&panel.querySelector('#search-form')===form;let busy=false;
 panel.innerHTML=card('网络搜索',`<div class="config-heading"><p>工作空间 <code>${esc(p.workspace_id)}</code> · 已保存版本 v${esc(p.version)} · ${p.enabled?'总开关开启':'总开关关闭'}</p><span class="badge">${p.can_configure?'可管理配置':'只读配置'}</span></div><p>搜索配置独立于 B5 模型出口代理。关闭总开关不清除 Agent 的 web_search 偏好；配置权限不授予搜索消费权限。</p><form id="search-form" class="config-form"><fieldset ${p.can_configure?'':'disabled'}><label class="check-label"><input type="checkbox" name="enabled" ${p.enabled?'checked':''}>启用当前工作空间网络搜索</label><label>搜索来源<select name="source"><option value="brave-free" ${p.source==='brave-free'?'selected':''}>Brave Search · 免费方案（需自行申请 Key / 核对额度）</option><option value="tavily" ${p.source==='tavily'?'selected':''}>Tavily（可能产生提供方费用）</option><option value="ddgs" disabled>DDGS · 不可用：依赖 / 协议未评估</option><option value="deepseek" disabled>DeepSeek · 不可用：官方 Anthropic 服务端工具额外模型费用，OpenAI 兼容不支持</option></select></label><p>未实现 DDGS / DeepSeek，不将模型能力当作免费搜索。提供方费用与额度以其账户为准。</p><label>API Key 操作<select name="secret_action"><option value="keep">保持已保存 Key</option><option value="replace">替换 Key</option><option value="clear">清除 Key</option></select></label><p>${p.has_key?'后端已保存 Key · 不回显':'尚未保存 Key'}</p><label>新 API Key<input type="password" name="api_key" autocomplete="new-password" value=""></label><section class="config-section"><h3>搜索专用代理</h3><label class="check-label"><input type="checkbox" name="proxy_enabled" ${p.proxy?.enabled?'checked':''}>启用搜索专用代理</label><label>代理地址（空为直连，不含凭据）<input name="proxy_url" value="${esc(p.proxy?.url||'')}" placeholder="http://127.0.0.1:7890 或 socks5://127.0.0.1:1080" autocomplete="off" maxlength="1000"></label><p>仅 HTTP CONNECT 与 SOCKS5；不读取环境代理，不继承全局模型出口。显式代理失败不直连兜底。HTTP CONNECT 凭据仅用于可信代理链路。</p><label>代理凭据操作<select name="proxy_secret_action"><option value="keep">保持已保存凭据</option><option value="replace">替换用户名与密码</option><option value="clear">清除凭据</option></select></label><p>${p.proxy?.has_credentials?'后端已保存代理凭据 · 不回显':'尚未保存代理凭据'}</p><label>新用户名<input name="proxy_username" autocomplete="off" value=""></label><label>新密码<input name="proxy_password" type="password" autocomplete="new-password" value=""></label></section><button id="search-save" type="submit" class="primary">保存网络搜索配置</button></fieldset><p id="search-message" role="status" aria-live="polite">${esc(message||(!p.can_configure?'只读：缺少 system.configure，不能保存。':''))}</p></form><section class="config-section"><h3>测试已保存配置</h3><p>测试仅发送下面手动输入的查询；不会发送表单未保存的来源、Key 或代理，不从群历史自动拼查询。需要 model.request + operator.read，system.configure 不等于消费授权；测试可能消耗提供方额度。</p><p>每次仅调用 1 次；查询上限 512 UTF-8 字节、最多 5 条结果、响应上限 256 KiB、后端超时 10 秒、每 workspace 并发上限 2；不重试、不抓取网页正文。结果 URL 仅展示，不自动访问。</p><form id="search-test-form" class="config-form"><label>测试查询<input name="query" required autocomplete="off" maxlength="512" placeholder="手动输入查询（最多 512 UTF-8 字节）"></label><button id="search-test" type="submit" ${p.enabled?'':'disabled'}>测试已保存的 v${esc(p.version)} 配置</button></form><div id="search-receipt" role="status" aria-live="polite">${p.enabled?'尚未测试。':'已保存总开关关闭；须保存启用后才可测试。'}</div></section>`);
 const form=$('#search-form'),testForm=$('#search-test-form'),save=$('#search-save'),test=$('#search-test'),msg=$('#search-message'),receipt=$('#search-receipt');
 const lock=value=>{busy=value;save.disabled=value||!p.can_configure;test.disabled=value||!p.enabled};
 form.onsubmit=async e=>{e.preventDefault();if(!current()||!p.can_configure||busy)return;const d=new FormData(form),action=d.get('secret_action'),pa=d.get('proxy_secret_action'),key=String(d.get('api_key')||''),username=String(d.get('proxy_username')||''),password=String(d.get('proxy_password')||'');if(action!=='replace'&&key||pa!=='replace'&&(username||password)){msg.textContent='填写新密钥 / 凭据时须明确选择替换；保持 / 清除不能携带新值。';return}const source=d.get('source');if(!['brave-free','tavily'].includes(source)){msg.textContent='请选择已支持的来源。';return}const url=String(d.get('proxy_url')||'').trim();if(url){try{const u=new URL(url);if(!['http:','socks5:'].includes(u.protocol)||!u.hostname||u.username||u.password||u.search||u.hash||u.pathname&&u.pathname!=='/')throw Error('invalid')}catch{msg.textContent='代理地址仅允许无凭据的 HTTP CONNECT / SOCKS5 地址，不允许路径、查询或片段。';return}}lock(true);msg.textContent='正在保存并重新读取持久配置…';try{await api(searchSettingsPath,{method:'PUT',body:JSON.stringify({enabled:d.has('enabled'),source,expected_version:p.version,secret_action:action,api_key:key,proxy:{enabled:d.has('proxy_enabled'),url,secret_action:pa,username,password}})},current);if(!current())return;const raw=await api(searchSettingsPath,{},current);if(current())renderSearchSettings(raw.data,session,seq,'保存成功 · 已重新读取持久配置。')}catch(err){if(current())msg.textContent='保存失败或未确认：'+err.message+'。409 请刷新核对版本，不自动覆盖；请勿直接重复提交。'}finally{for(const name of ['api_key','proxy_username','proxy_password'])form.elements.namedItem(name).value='';if(current())lock(false)}};
 testForm.onsubmit=async e=>{e.preventDefault();if(!current()||busy||!p.enabled)return;const query=String(new FormData(testForm).get('query')||'').trim();if(!query||new TextEncoder().encode(query).length>512){receipt.textContent='请输入非空查询，最多 512 UTF-8 字节（中文通常占多字节）。';return}lock(true);receipt.textContent='正在测试后端已保存配置；不使用未保存表单值，不自动重试…';try{const raw=await api(searchSettingsPath+'/test',{method:'POST',body:JSON.stringify({query})},current);if(!current())return;const r=raw.data;if(!r||r.workspace_id!==p.workspace_id||!r.request_id||!Array.isArray(r.results)||r.results.length>5||!['success','no_results'].includes(r.status))throw Error('搜索回执缺失或范围不符');receipt.innerHTML=`<p>工作空间 ${esc(r.workspace_id)} · 请求 ${esc(r.request_id)} · 配置 v${esc(r.config_version)} · 来源 ${esc(r.source)} · 状态 ${esc(r.status)} · 耗时 ${esc(r.elapsed_ms)} ms</p>${r.config_version!==p.version?'<p>后端实际使用的配置版本已变化，请刷新核对。</p>':''}${r.status==='no_results'?'<p>搜索成功 · 无结果（与提供方失败不同）</p>':''}<ol>${r.results.map(x=>`<li><strong>${esc(x.title)}</strong><p>${esc(x.url)}</p><p>${esc(x.snippet)}</p></li>`).join('')}</ol>`}catch(err){if(current())receipt.textContent='搜索失败 / 未确认：'+err.message+'。无成功结果，不自动重试；超时不表示后端未发生消费。'}finally{if(current())lock(false)}};
}
const proxySettingsPath='/v1/operator/system/global-proxy';
function proxyPanel(){return '<div id="proxy-panel">'+card('全局出口代理','<p>正在读取当前工作空间配置…</p>')+'</div>'}
async function loadProxySettings(session,seq){const current=()=>settingsCurrent(session,seq);try{const raw=await api(proxySettingsPath,{},current);if(current())renderProxySettings(raw.data,session,seq)}catch(e){if(current()&&$('#proxy-panel'))$('#proxy-panel').innerHTML=card('全局出口代理 · 不可用','<p role="alert">读取失败：'+esc(e.message)+'。需要启用受保护模型注册器及 system.read；不显示直连值冒充有效配置，无法保存。</p>')}}
function renderProxySettings(p,session,seq,message=''){
 const current=()=>settingsCurrent(session,seq);if(!current()||!$('#proxy-panel'))return;
 $('#proxy-panel').innerHTML=card('全局出口代理',`<div class="config-heading"><p>工作空间 <code>${esc(p.workspace_id)}</code> · <span id="proxy-version">v${esc(p.version)}</span> · ${p.enabled?'已启用':'直连（未启用）'}</p><span class="badge">${p.can_configure?'可管理出口':'只读权限'}</span></div><p>当前 workspace 应用级外部 HTTP 默认，不是系统 VPN、宿主环境变量或 QQ / 数据库全流量代理。</p><form id="proxy-form" class="config-form"><fieldset ${p.can_configure?'':'disabled'}><label><input type="checkbox" name="enabled" id="proxy-enabled" ${p.enabled?'checked':''}>启用模型出口代理</label><label>代理地址（不含凭据，必须含端口）<input id="proxy-url" name="url" value="${esc(p.url)}" placeholder="http://127.0.0.1:7890 或 socks5://127.0.0.1:1080" autocomplete="off" maxlength="1000"></label><p>仅支持 HTTP CONNECT 与 SOCKS5；不提供 HTTPS / SOCKS4 / socks5h 或任意 URL 探测。SOCKS5 使用本地 DNS 和数值目标，不交给代理重新解析。HTTP CONNECT 凭据未经代理 TLS 加密，限可信代理链路。</p><label>凭据操作<select id="proxy-action" name="secret_action"><option value="keep">保持（留空不变）</option><option value="replace">替换用户名和密码</option><option value="clear">清除已保存凭据</option></select></label><p id="proxy-secret-state">${p.has_credentials?'后端已保存凭据 · 用户名 / 密码均不回显':'未保存代理凭据'}</p><label>新用户名<input id="proxy-username" name="username" autocomplete="off" maxlength="255"></label><label>新密码<input id="proxy-password" name="password" type="password" autocomplete="new-password" maxlength="255"></label><button id="proxy-save" class="primary" type="submit">保存出口配置</button></fieldset><p id="proxy-message" role="status">${esc(message||(!p.can_configure?'只读：缺少 system.configure，API 同样拒绝修改。':''))}</p></form><h3>已覆盖与生效时机</h3><p>已注册模型的连接测试、workspace 默认规划、Agent 绑定模型规划，以及注册器无模型时的既有 HTTP provider 后备。下一次新模型调用读取不可变快照；已开始调用不改道、不重试、不重发。未启用注册器的启动 provider 保持无环境代理直连，不能消费此设置。</p><p>连接测试仍在 LLM 页面，只使用已保存并授权的模型端点；原模型预算、并发、超时、错误与端点审批契约不变。</p><h3>内网与失败边界</h3><p>默认 bypass loopback / private / link-local / 非公网地址及内部控制端口。DNS 答案含本地地址则整次直连，不经代理；代理自身允许本地地址，但不允许转发本地目标。TLS 校验保留，模型仍不跟随重定向；私有 HTTP 仅原有精确审批可用。</p><p>未配置兼容直连；存储读取失败拒绝调用；显式代理失败不直连兜底。每次调用独立连接，无跨 workspace / 模型连接池。6300、NapCat、task-bridge、数据库不消费此设置。</p><h3>未覆盖（不冒称全局已接完）</h3><p>网络搜索下一批接入，保留其独立出口语义；通知、插件、Character 自有外部模型客户端尚未接入。保存不授予任何 QQ 写或执行权限。</p>`);
 $('#proxy-form').onsubmit=async e=>{e.preventDefault();if(!current()||!p.can_configure||state.proxyBusy)return;const f=new FormData(e.target),action=f.get('secret_action'),username=f.get('username'),password=f.get('password');if(action!=='replace'&&(username||password)){$('#proxy-message').textContent='填写新凭据时须明确选择替换；保持 / 清除不能携带新凭据。';return}state.proxyBusy=true;$('#proxy-save').disabled=true;$('#proxy-message').textContent='正在保存并重新读取…';try{await api(proxySettingsPath,{method:'PUT',body:JSON.stringify({enabled:f.has('enabled'),url:f.get('url').trim(),expected_version:p.version,secret_action:action,username,password})},current);if(!current())return;const raw=await api(proxySettingsPath,{},current);if(current())renderProxySettings(raw.data,session,seq,'保存成功 · 已重新读取持久配置；下一次新模型调用生效。')}catch(err){if(current())$('#proxy-message').textContent='保存失败：'+err.message+'。未确认保存；409 请刷新核对，不自动覆盖。'}finally{if(current()){state.proxyBusy=false;if($('#proxy-save'))$('#proxy-save').disabled=!p.can_configure;$('#proxy-username').value='';$('#proxy-password').value=''}}};
}

// B3: content rules are configuration, not sending authority.
function contentCurrent(s,q,k,d){return s===state.session&&q===state.seq&&k===state.route&&(d===undefined||d===state.detailSeq&&$('#details').open)}
const contentDecisions={allowed:'规则未命中',blocked:'命中阻断',unsupported:'类型不支持'};
function ruleBody(p){return {name:p.name,kind:p.kind,expression:p.expression,case_sensitive:p.case_sensitive,group:p.group,priority:p.priority,enabled:p.enabled,expected_version:p.version||0}}
async function loadContent(q){const s=state.session,k=state.route,current=()=>contentCurrent(s,q,k);state.contentCan=false;state.contentItems=[];$('#refresh').disabled=false;$('#content').innerHTML='<div class="loading">正在读取内容规则与审核证据…</div>';try{const qs=k==='approvals'?'?limit=20&offset='+(state.reviewOffset||0)+'&decision='+encodeURIComponent(state.reviewDecision||'')+'&account_id='+encodeURIComponent(state.reviewAccount||'')+'&send_id='+encodeURIComponent(state.reviewSend||''):'';const raw=await api('/v1/operator/'+(k==='intercept'?'content-rules':'content-reviews')+qs,{},current);if(!current())return;state.contentItems=raw.data.items;state.contentCan=raw.data.can_configure===true;$('#connection').textContent=state.contentCan?'已认证 · 内容规则管理':'已认证 · 内容记录查看';$('#updated').textContent='仅单段纯文本 gateway 与申请文本门 · 不提供发送授权 · 未支持消息不可执行';if(k==='intercept'){
$('#content').innerHTML=card('拦截规则',`<div class="config-heading"><div><p>工作空间隔离 · 版本 ${esc(raw.data.version)} · ${raw.data.items.length} 条规则</p><p>无规则不是读取失败。默认不安装真实禁词，不自动采集或发送。</p></div>${state.contentCan?'<button id="rule-new" class="primary">新建规则</button>':'<span class="badge">只读权限</span>'}</div><p>关键词按字面匹配；模式使用 Go RE2，不支持回溯/后行断言。大小写可选 Unicode 简单折叠，不做 NFKC/同形字归一化。单条文本最多 8192 UTF-8 字节；模式最多 512 字节。换行原样保留，点号默认不跨行，可显式 (?s)。多段发送本批阻断。</p><button id="rule-preview">试跑已保存规则</button><div id="content-message" role="status"></div>`)+`<div class="config-grid">${raw.data.items.map(p=>`<section class="card config-card"><h2>${esc(p.name)}</h2><span class="badge ${p.enabled?'blue':''}">${p.enabled?'已启用':'已停用'}</span><p>${p.kind==='keyword'?'关键词':'受限模式'} · ${esc(p.group||'未分组')} · 优先级 ${esc(p.priority)} · v${esc(p.version)}</p><pre>${esc(p.expression)}</pre><small>${p.case_sensitive?'区分大小写':'忽略大小写'}</small><div class="config-actions"><button data-rule-edit="${esc(p.id)}">${state.contentCan?'编辑':'查看'}</button><button data-rule-history="${esc(p.id)}">版本历史</button>${state.contentCan?`<button data-rule-toggle="${esc(p.id)}">${p.enabled?'禁用':'启用'}</button><button data-rule-delete="${esc(p.id)}" class="danger">删除</button>`:''}</div></section>`).join('')}</div>`+(raw.data.items.length?'':empty('暂无拦截规则','规则集准确为空；请配置认可的规则后启用，仍须原有发送许可'));
}else{const items=raw.data.items;$('#content').innerHTML=card('审批记录 · 内容审核',`<p>允许/阻断记录不等于发送成功。仅展示 payload 摘要、命中位置和规则版本，不保存或回显发送原文。误报说明不会重发或授予许可。</p><form id="review-filter" class="toolbar"><label>审核结果<select name="decision"><option value="">全部</option>${Object.entries(contentDecisions).map(([v,n])=>`<option value="${v}" ${state.reviewDecision===v?'selected':''}>${n}</option>`).join('')}</select></label><label>账号标识<input name="account" value="${esc(state.reviewAccount||'')}"></label><label>发送标识<input name="send" value="${esc(state.reviewSend||'')}"></label><button>筛选</button></form><div class="table-wrap"><table><thead><tr><th>审核结果</th><th>账号 / 会话</th><th>发送标识</th><th>规则集版本</th><th>时间</th></tr></thead><tbody>${items.map(p=>`<tr><td><button data-review="${esc(p.id)}">${esc(contentDecisions[p.decision]||p.decision)}</button></td><td>${esc(p.account_id)}<small>${esc(p.conversation_kind)} / ${esc(p.conversation_id)}</small></td><td>${esc(p.send_id)}</td><td>${esc(p.rules_version)}</td><td>${esc(new Date(p.created_at).toLocaleString('zh-CN'))}</td></tr>`).join('')}</tbody></table></div>${items.length?'':empty('暂无审核记录','当前筛选下没有记录；试跑不会产生发送审核记录')}<div class="pagination"><button id="reviews-prev" ${(state.reviewOffset||0)>0?'':'disabled'}>上一页</button><span>已偏移 ${esc(raw.data.offset)} 条</span><button id="reviews-next" ${raw.data.has_more?'':'disabled'}>下一页</button></div>`);$('#review-filter').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);state.reviewDecision=d.get('decision');state.reviewAccount=d.get('account');state.reviewSend=d.get('send');state.reviewOffset=0;load()};$('#reviews-prev').onclick=()=>{state.reviewOffset=Math.max(0,(state.reviewOffset||0)-20);load()};$('#reviews-next').onclick=()=>{state.reviewOffset=raw.data.next_offset;load()};}
}catch(e){if(!current())return;$('#content').innerHTML=empty('内容管理不可用','读取失败不会当成空规则集或允许发送');$('#error').textContent='读取失败：'+e.message;$('#error').hidden=false}}
function ruleForm(id=''){const p=state.contentItems.find(x=>x.id===id)||{name:'',kind:'keyword',expression:'',case_sensitive:true,group:'',priority:100,enabled:false,version:0},can=state.contentCan;clearDetail();const s=state.session,q=state.seq,k=state.route,d=state.detailSeq,current=()=>contentCurrent(s,q,k,d);$('#detail-title').textContent=(can?(id?'编辑':'新建'):'查看')+'拦截规则';$('#detail-body').innerHTML=`<form id="rule-form" class="config-form"><fieldset ${can?'':'disabled'}>${configField('名称','name',p.name)}<label>匹配类型<select name="kind"><option value="keyword" ${p.kind==='keyword'?'selected':''}>关键词字面</option><option value="pattern" ${p.kind==='pattern'?'selected':''}>受限模式（Go RE2）</option></select></label>${configField('匹配内容 / 模式','expression',p.expression,true)}${configField('规则分组','group',p.group)}<label>优先级（高优先，0–10000）<input name="priority" type="number" min="0" max="10000" value="${esc(p.priority)}" required></label><label><input name="case_sensitive" type="checkbox" ${p.case_sensitive?'checked':''}>区分大小写</label><label><input name="enabled" type="checkbox" ${p.enabled?'checked':''}>启用（不会新增发送授权）</label></fieldset><p>当前版本 v${esc(p.version)} · 保存校验 expected_version；冲突不会覆盖他人修改。</p>${can?'<button class="primary">保存规则</button>':''}<p id="content-form-error" role="alert"></p></form>`;$('#details').showModal();$('#rule-form').onsubmit=e=>{e.preventDefault();if(!can||!current())return;const f=new FormData(e.target);contentWrite('/content-rules'+(id?'/'+encodeURIComponent(id):''),id?'PUT':'POST',{name:f.get('name'),kind:f.get('kind'),expression:f.get('expression'),group:f.get('group'),priority:Number(f.get('priority')),case_sensitive:f.has('case_sensitive'),enabled:f.has('enabled'),expected_version:p.version},current)}}
async function contentWrite(path,method,body,current){if(state.contentBusy)return;state.contentBusy=true;const controls=[...document.querySelectorAll('#detail-body button')];controls.forEach(x=>x.disabled=true);try{await api('/v1/operator'+path,{method,body:JSON.stringify(body)},current);if(!current())return;clearDetail();await load()}catch(e){if(current()){const t=$('#content-form-error');if(t)t.textContent='操作失败：'+e.message+'；版本冲突请关闭并刷新，未覆盖当前记录。'}}finally{if(current()){state.contentBusy=false;controls.forEach(x=>x.disabled=false)}}}
function ruleConfirm(id,action){const p=state.contentItems.find(x=>x.id===id);if(!p||!state.contentCan)return;clearDetail();const s=state.session,q=state.seq,k=state.route,d=state.detailSeq,current=()=>contentCurrent(s,q,k,d);$('#detail-title').textContent=action==='delete'?'删除规则':p.enabled?'禁用规则':'启用规则';$('#detail-body').innerHTML=`<p>${esc(p.name)} · v${esc(p.version)}。保留历史，不提供自动发送许可。</p><button id="rule-confirm">确认</button><p id="content-form-error" role="alert"></p>`;$('#details').showModal();$('#rule-confirm').onclick=()=>contentWrite('/content-rules/'+encodeURIComponent(id),action==='delete'?'DELETE':'PUT',action==='delete'?{expected_version:p.version}:{...ruleBody(p),enabled:!p.enabled},current)}
async function contentHistory(id){clearDetail();const s=state.session,q=state.seq,k=state.route,d=state.detailSeq,current=()=>contentCurrent(s,q,k,d);$('#detail-title').textContent='规则版本历史';$('#detail-body').textContent='正在读取历史…';$('#details').showModal();try{const raw=await api('/v1/operator/content-rules/'+encodeURIComponent(id)+'/history',{},current);if(current())$('#detail-body').innerHTML='<p>只读快照，不提供回滚发送权。</p>'+raw.data.items.map(x=>`<details><summary>v${esc(x.version)} · ${esc(x.updated_by)} · ${esc(x.updated_at)}</summary><pre>${esc(JSON.stringify(x,null,2))}</pre></details>`).join('')}catch(e){if(current())$('#detail-body').textContent='读取失败：'+e.message}}
function contentPreview(){clearDetail();const s=state.session,q=state.seq,k=state.route,d=state.detailSeq,current=()=>contentCurrent(s,q,k,d);$('#detail-title').textContent='规则试跑 · 不发送';$('#detail-body').innerHTML='<form id="preview-form" class="config-form"><label>待检查单段文本<textarea name="text" rows="5" required></textarea></label><p>使用当前已保存且启用规则，不发放许可、不调用 writer。多段、媒体、嵌套转发不支持。</p><button>检查文本</button><pre id="preview-result"></pre></form>';$('#details').showModal();$('#preview-form').onsubmit=async e=>{e.preventDefault();try{const raw=await api('/v1/operator/content-rules/preview',{method:'POST',body:JSON.stringify({text:new FormData(e.target).get('text')})},current);if(current())$('#preview-result').textContent=JSON.stringify(raw.data,null,2)}catch(e){if(current())$('#preview-result').textContent='试跑失败：'+e.message}}}
async function reviewDetail(id){clearDetail();const s=state.session,q=state.seq,k=state.route,d=state.detailSeq,current=()=>contentCurrent(s,q,k,d);$('#detail-title').textContent='内容审核详情';$('#detail-body').textContent='正在读取脱敏证据…';$('#details').showModal();try{const raw=await api('/v1/operator/content-reviews/'+encodeURIComponent(id),{},current);if(!current())return;const p=raw.data;$('#detail-body').innerHTML=`<p>${esc(contentDecisions[p.decision])} · 规则集版本 ${esc(p.rules_version)}</p><p>记录不授予权限，修订后须使用原业务重新提交并重检；本页不重发。</p><dl>${['id','account_id','conversation_kind','conversation_id','send_id','task_id','payload_digest'].map(key=>`<dt>${esc(key)}</dt><dd>${esc(p[key]||'无关联')}</dd>`).join('')}</dl><pre>${esc(JSON.stringify(p.evidence,null,2))}</pre><h3>误报 / 修订说明</h3>${p.notes.map(n=>`<p>${esc(n.note)} · ${esc(n.updated_by)}</p>`).join('')||'<p>暂无说明</p>'}${p.can_note?'<form id="review-note" class="config-form"><label>仅记录必要说明，请勿粘贴敏感原文<textarea name="note" maxlength="1000" required></textarea></label><button>保存说明（不重发）</button><p id="content-form-error" role="alert"></p></form>':'<p>只读权限 · 不可记录说明</p>'}`;if(p.can_note)$('#review-note').onsubmit=e=>{e.preventDefault();contentWrite('/content-reviews/'+encodeURIComponent(id)+'/notes','POST',{note:new FormData(e.target).get('note')},current)}}catch(e){if(current())$('#detail-body').textContent='读取失败：'+e.message}}
document.addEventListener('click',e=>{if(e.target.closest('#rule-new')){if(state.contentCan)ruleForm();return}if(e.target.closest('#rule-preview')){contentPreview();return}const rev=e.target.closest('[data-review]');if(rev){reviewDetail(rev.dataset.review);return}for(const a of ['edit','history','toggle','delete']){const el=e.target.closest('[data-rule-'+a+']');if(!el||state.route!=='intercept')continue;const id=el.getAttribute('data-rule-'+a);if(a==='edit')ruleForm(id);else if(a==='history')contentHistory(id);else ruleConfirm(id,a);return}});
function toolRender(){const q=($('#tool-search')?.value||'').toLowerCase(),category=$('#tool-category')?.value||'';const entries=state.registry.entries.filter(x=>(!category||x.category===category)&&(!q||[x.id,x.name,x.category].some(s=>s.toLowerCase().includes(q))));$('#tool-count').textContent=`筛选 ${entries.length} / ${state.registry.entry_count} 项 · 唯一标识 ${state.registry.unique_count}`;$('#tool-results').innerHTML=entries.length?entries.map(x=>`<section class="card tool-card"><h2>${esc(x.name)}</h2><code>${esc(x.id)}</code><p>${esc(x.category)} · 参数未核验 · 实例支持未知</p><span class="badge ${x.risk.includes('blocked')?'red':''}">${x.risk.includes('blocked')?'敏感能力 · 禁止输出绕过':'仅注册 · 未启用'}</span>${x.alias_candidate?`<p>候选别名 ${esc(x.alias_candidate)}（未验证，不自动归并）</p>`:''}</section>`).join(''):empty('未找到工具','尝试原始标识、中文名或分类')};
async function load(more=false){const seq=++state.seq;$('#error').hidden=true;$('#auth').hidden=!!state.token;if(!state.token){$('#content').innerHTML=empty('等待操作员认证','不会连接外部平台或读取未授权账号');return}if(state.route==='settings'){await loadWorkSettings(seq);return}if(['intercept','approvals'].includes(state.route)){await loadContent(seq);return}if(['agents','skills'].includes(state.route)){await loadConfig(seq);return}if(state.route==='llm'){await loadModels(seq);return}if(state.route==='chat'){await loadChat(seq);return}if(state.route==='notify'){await loadNotify(seq);return}if(!['dashboard','tasks','tools'].includes(state.route)){pending();return}if(!more)$('#content').innerHTML='<div class="loading">正在读取已认证后端…</div>';$('#refresh').disabled=true;try{if(state.route==='dashboard'){const result=await api('/v1/operator/dashboard');if(seq!==state.seq)return;dashboard(result.data)}else if(state.route==='tasks'){const raw=await api('/v1/tasks?limit=50'+(more&&state.taskCursor?'&cursor='+encodeURIComponent(state.taskCursor):''));if(seq!==state.seq)return;state.taskItems=more?state.taskItems.concat(raw.data.items):raw.data.items;state.taskCursor=raw.meta.next_cursor||'';$('#content').innerHTML=qq03CreateCard()+card('任务列表',taskTable(state.taskItems)+(raw.meta.has_more?'<div class="pagination"><button id="tasks-more">加载更多</button></div>':''));const qq03form=$('#qq03-create-form');if(qq03form)qq03form.onsubmit=qq03CreateFormAction;$('#updated').textContent=`已加载 ${state.taskItems.length} 项 · 仅当前权限范围`}else{const raw=await api('/v1/operator/tools');if(seq!==state.seq)return;state.registry=raw;$('#content').innerHTML=`<section class="card"><h2>NapCat 工具目录</h2><p id="tool-count"></p><p>此目录来自用户原始清单；不启动调用，不伪造 schema。凭据、原始包及快速操作不会绕过输出门。</p><div class="toolbar"><input id="tool-search" aria-label="检索工具" placeholder="搜索原始标识 / 中文名称"><select id="tool-category" aria-label="工具分类"><option value="">全部分类</option>${[...new Set(raw.entries.map(x=>x.category))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div></section><div id="tool-results" class="tool-grid"></div>`;toolRender();$('#updated').textContent=`注册 ${raw.entry_count} 条 · 唯一 ${raw.unique_count} · 重复标识 ${Object.keys(raw.duplicates).length} · 别名候选 ${raw.alias_candidates.length}`};$('#connection').textContent='已认证 · 只读'}catch(e){if(seq!==state.seq)return;$('#error').textContent=`读取失败：${e.message}。当前数据不可用，请重试；未将离线当作正常。`;$('#error').hidden=false;$('#content').innerHTML=empty('数据不可用','没有使用旧数据或演示数字替代');$('#connection').textContent='连接异常';$('#updated').textContent='本次读取失败 · 无缓存数据'}finally{if(seq===state.seq)$('#refresh').disabled=false}}
async function detail(id){const session=state.session,seq=++state.detailSeq;const current=()=>session===state.session&&seq===state.detailSeq&&$('#details').open;$('#detail-title').textContent='任务详情';$('#detail-body').textContent='正在读取…';if(!$('#details').open)$('#details').showModal();try{const {data:t}=await api('/v1/tasks/'+encodeURIComponent(id),{},current);let slotsNote;try{const snap=await api('/v1/operator/system/task-work-slots/'+encodeURIComponent(id),{},current);slotsNote=snap.data.work_slots===null?'尚未首次启动 · 未固化':String(snap.data.work_slots)+' 个 / 任务（已固化）'}catch(e){slotsNote='固化值读取不可用：'+e.message} if(!current())return;$('#detail-title').textContent=t.title||'任务详情';const rows=[['任务标识',t.id],['类型',qq03TypeLabels[t.type]||t.type],['状态',labels[t.state]||t.state],['工作槽位',slotsNote],['目标数量',t.goal_count],['已确认结果',t.confirmed_unique_count],['等待外部结果',t.pending_external_count],['未知执行',t.unknown_execution_count],['阻塞原因',t.blocked_reason||'无'],['作用域版本',t.scope_revision],['执行模式',t.execution_mode==='dry_run'?'隔离试运行':t.execution_mode],['截止时间',new Date(t.deadline_at).toLocaleString('zh-CN')]];$('#detail-body').innerHTML=`<dl>${rows.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><p>只读详情；现有暂停 / 恢复 / 取消仍在兼容控制台，未改旧契约。</p>`}catch(e){if(current())$('#detail-body').textContent='详情读取失败：'+e.message}}
document.addEventListener('click',e=>{const link=e.target.closest('[data-route]');if(link){e.preventDefault();history.pushState({},'',link.href);route();return}const task=e.target.closest('[data-task]');if(task)detail(task.dataset.task);const tab=e.target.closest('[data-tab]');if(tab){document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===tab)));$('#pending-title').textContent=tab.dataset.tab==='QQ'?'QQ 收件箱 · 待接入':'Agent 对话 · 待接入'}if(e.target.id==='tasks-more')load(true)});
document.addEventListener('input',e=>{if(e.target.id==='tool-search')toolRender()});document.addEventListener('change',e=>{if(e.target.id==='tool-category')toolRender()});$('#connect-form').addEventListener('submit',e=>{e.preventDefault();const token=$('#credential').value.trim();resetSession();state.token=token;load()});$('#refresh').onclick=()=>load();$('#logout').onclick=()=>{resetSession();load()};$('#menu').onclick=()=>{$('#sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String($('#sidebar').classList.contains('open')))};$('#theme').onclick=()=>document.documentElement.classList.toggle('dark');$('#close-detail').onclick=clearDetail;$('#details').addEventListener('cancel',e=>{e.preventDefault();clearDetail()});$('#details').addEventListener('close',()=>{if(!$('#details').open)clearDetail()});$('#legal').onclick=()=>{clearDetail();$('#detail-title').textContent='开源许可与来源';$('#detail-body').textContent='BBA 第一批产品界面参考并适配 ARTEX v0.3.24（e740334b）。主题变量、Card 和侧栏布局来源见源码 frontend/NOTICE。ARTEX 根 LICENSE 为 AGPL-3.0，web/LICENSE 为 MIT（Copyright 2024 Mohammed Arham Khan）。保留两份许可，不宣称整个上游为 MIT。修改源码位于本项目 frontend 与 backend；对外发布前仍需完成逐文件许可覆盖核对。本软件不提供担保。';$('#details').showModal()};window.addEventListener('popstate',route);setInterval(()=>{if(state.token&&state.route==='dashboard'&&!document.hidden&&!$('#refresh').disabled)load()},15000);route();
const chatKindLabel={group:'群聊',private:'私聊',agent:'Agent 线程'};const chatDelivery={received:'已接收',draft:'草稿',review:'待审核',queued:'排队中',blocked_by_rule:'规则阻断',local_record:'本地记录'};const chatScope=['Agent 流式输出、停止与可追溯工具结果','QQ 出站仅草稿、规则与许可回执；真实发送未授权'];const notifyScope=['事件订阅规则与失败重试 · 投递仅本地记录'];
async function chatPages(path,current){const items=[],seen=new Set();let cursor='';for(;;){const raw=await api(path+'?limit=50'+(cursor?'&cursor='+encodeURIComponent(cursor):''),{},current);if(!current())return null;if(!raw.data||!Array.isArray(raw.data.items))throw new Error('响应格式未知');items.push(...raw.data.items);const next=raw.data.next_cursor;if(!next)return items;if(seen.has(next))throw new Error('分页游标重复');seen.add(next);cursor=next}}
async function loadChat(seq){const s=state.session,current=()=>s===state.session&&seq===state.seq&&state.route==='chat';state.chatTab=state.chatTab||'agent';$('#content').innerHTML='<div class="loading">正在读取双对话视图…</div>';try{const items=await chatPages('/v1/operator/conversations',current);if(!current())return;state.chatItems=items;state.chatConv='';state.chatMsgs=[];renderChat()}catch(e){if(current()){$('#content').innerHTML=card('双对话视图','<p role="alert">读取失败：'+esc(e.message)+'；读取失败不会当成空态。</p>'+pendingScope(chatScope));$('#error').textContent='双对话读取失败：'+e.message+'；未当作空态。';$('#error').hidden=false}}}
function renderChat(){const items=(state.chatItems||[]).filter(x=>x.kind===(state.chatTab==='qq'?'qq':'agent'));const tabs='<div class="tabs" role="tablist" id="chat-tabs"><button role="tab" id="chat-tab-agent" aria-selected="'+(state.chatTab==='agent')+'" data-chat-tab="agent">Agent 对话</button><button role="tab" id="chat-tab-qq" aria-selected="'+(state.chatTab==='qq')+'" data-chat-tab="qq">QQ 收件箱</button></div>';const list=items.length?`<div class="table-wrap"><table><thead><tr><th>会话</th><th>账号</th><th>类型</th><th>最后事件</th><th>未读</th><th>版本</th></tr></thead><tbody>${items.map(x=>`<tr><td><button data-chat-conv="${esc(x.id)}">${esc(x.conversation_id||x.id)}</button></td><td>${esc(x.account_id||'未映射')}</td><td>${esc(chatKindLabel[x.conversation_kind]||x.conversation_kind)}</td><td>${esc(x.last_event_at?new Date(x.last_event_at).toLocaleString('zh-CN'):'—')}</td><td>${fmt(x.unread_count)}</td><td>${fmt(x.version)}</td></tr>`).join('')}</tbody></table></div>`:empty(state.chatTab==='qq'?'QQ 收件箱暂无会话':'Agent 对话暂无会话','当前权限范围内没有真实数据；不展示演示数据');const conv=(state.chatItems||[]).find(x=>x.id===state.chatConv);const msgs=state.chatMsgs||[];const detail=conv?card((conv.conversation_id||conv.id)+' · '+(chatKindLabel[conv.conversation_kind]||conv.conversation_kind),(msgs.length?`<div class="table-wrap"><table><thead><tr><th>#</th><th>来源</th><th>方向</th><th>状态</th><th>内容/摘要</th><th>时间</th></tr></thead><tbody>${msgs.map(m=>`<tr><td>${fmt(m.seq)}</td><td>${esc(m.source)}</td><td>${esc(m.direction)}</td><td><span class="badge ${['draft','blocked_by_rule'].includes(m.delivery_state)?'amber':''}">${esc(chatDelivery[m.delivery_state]||m.delivery_state)}</span></td><td>${esc(m.body||('摘要 '+m.body_digest))}</td><td>${esc(new Date(m.created_at).toLocaleString('zh-CN'))}</td></tr>`).join('')}</tbody></table></div>`:empty('该会话暂无消息','仅展示真实读取结果；不展示演示数据'))+chatForm(conv)):'';$('#content').innerHTML=tabs+list+detail+pendingScope(chatScope);if(conv)bindChatForm(conv)}
function chatForm(conv){if(state.chatTab==='agent')return `<form id="chat-form" class="config-form"><label>Agent 消息内容（不会进入 QQ 出站）<textarea name="body" maxlength="8192" required></textarea></label><button id="chat-form-submit">保存消息</button><p id="chat-form-error" role="alert"></p></form>`;return `<form id="chat-form" class="config-form"><label>草稿内容（保存为草稿，不真实发送）<textarea name="body" maxlength="8192" required></textarea></label><input type="hidden" name="expected_version" value="${esc(conv.version)}"><button id="chat-form-submit">保存草稿</button><button type="button" disabled title="本轮未授权真实 QQ 发送；仅允许草稿与规则/许可回执">真实发送（未授权）</button><p id="chat-form-error" role="alert"></p></form>`}
function bindChatForm(conv){const f=$('#chat-form');if(!f)return;const session=state.session,seq=state.seq,tab=state.chatTab,current=()=>session===state.session&&seq===state.seq&&state.route==='chat'&&state.chatConv===conv.id&&state.chatTab===tab;f.onsubmit=async e=>{e.preventDefault();const body=new FormData(f).get('body');const key=self.crypto?.randomUUID?.()||('fk-'+Date.now());try{if(state.chatTab==='agent'){const r=await api('/v1/operator/agent-threads/'+encodeURIComponent(conv.id)+'/messages',{method:'POST',body:JSON.stringify({body}),headers:{'Idempotency-Key':key}},current);if(!current())return;state.chatMsgs.push({id:r.data.id,source:'agent',direction:'inbound',delivery_state:r.data.delivery_state,body,body_digest:r.data.body_digest,seq:state.chatMsgs.length+1,created_at:new Date().toISOString()});renderChat();$('#chat-form-error').textContent=`已保存 ${r.data.id} · 许可 ${r.data.send_permit}`}else{const r=await api('/v1/operator/qq-drafts',{method:'POST',body:JSON.stringify({account_id:conv.account_id,conversation_kind:conv.conversation_kind,conversation_id:conv.conversation_id,body,expected_version:Number(conv.version)}),headers:{'Idempotency-Key':key}},current);if(!current())return;state.chatMsgs.push({id:r.data.message_id||r.data.id,source:'qq',direction:'outbound_draft',delivery_state:r.data.decision==='blocked'?'blocked_by_rule':'draft',body,body_digest:r.data.payload_digest,seq:state.chatMsgs.length+1,created_at:new Date().toISOString()});renderChat();$('#chat-form-error').textContent=`草稿 ${r.data.id} · 规则判定 ${r.data.decision} · 许可 ${r.data.send_permit}`}}catch(e2){if(!current())return;const err=$('#chat-form-error');if(err)err.textContent='操作失败：'+e2.message+'；未覆盖当前记录。'}}}
async function loadChatMsgs(id){const s=state.session,q=state.seq,current=()=>s===state.session&&q===state.seq&&state.route==='chat'&&state.chatConv===id;try{const items=await chatPages('/v1/operator/conversations/'+encodeURIComponent(id)+'/messages',current);if(!current())return;state.chatMsgs=items;renderChat()}catch(e){if(current()){$('#error').textContent='消息读取失败：'+e.message+'；未当作空态。';$('#error').hidden=false}}}
async function loadNotify(seq){const s=state.session,current=()=>s===state.session&&seq===state.seq&&state.route==='notify';$('#content').innerHTML='<div class="loading">正在读取通知投影…</div>';try{const items=await chatPages('/v1/operator/notifications',current);if(!current())return;notifyRender(items)}catch(e){if(current()){$('#content').innerHTML=card('通知投影','<p role="alert">读取失败：'+esc(e.message)+'；读取失败不会当成空态。</p>'+pendingScope(notifyScope));$('#error').textContent='通知读取失败：'+e.message+'；未当作空态。';$('#error').hidden=false}}}
function notifyRender(items){const list=items.length?`<div class="table-wrap"><table><thead><tr><th>事件</th><th>账号 / 会话</th><th>摘要</th><th>投递</th><th>读取</th><th>时间</th><th></th></tr></thead><tbody>${items.map(n=>`<tr><td>${esc(n.event_type)}</td><td>${esc(n.account_id||'—')}<small>${esc(n.conversation_id||'无关联')}</small></td><td>${esc(n.summary)}</td><td>${esc(n.delivery_state==='local_only'?'本地记录':n.delivery_state)}</td><td><span class="badge ${n.read_at?'green':'amber'}">${n.read_at?'已读':'未读'}</span></td><td>${esc(new Date(n.created_at).toLocaleString('zh-CN'))}</td><td>${n.read_at?'':`<button data-notice-read="${esc(n.id)}" data-version="${esc(n.version)}">标记已读</button>`}</td></tr>`).join('')}</tbody></table>`:empty('暂无通知','当前权限范围内没有事件记录；不展示演示数据');$('#content').innerHTML=card('通知投影 · 本地记录',list+pendingScope(notifyScope));document.querySelectorAll('[data-notice-read]').forEach(b=>b.onclick=async()=>{const body={expected_version:Number(b.dataset.version),read:true};try{await api('/v1/operator/notifications/'+encodeURIComponent(b.dataset.noticeRead),{method:'POST',body:JSON.stringify(body),headers:{'Idempotency-Key':self.crypto?.randomUUID?.()||('nk-'+Date.now())}},()=>true);await loadNotify(state.seq)}catch(e){const t=$('#content-form-error')||$('#error');const msg='操作失败：'+e.message+'；CAS 冲突未覆盖当前记录。';if(t){t.textContent=msg;t.hidden=false}}})}
function pendingScope(items){return `<p class="muted">待接入范围：${items.map(esc).join('；')}</p>`}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-chat-tab]');if(tab&&state.route==='chat'){state.chatTab=tab.dataset.chatTab;state.chatConv='';state.chatMsgs=[];loadChat(state.seq);return}const cv=e.target.closest('[data-chat-conv]');if(cv&&state.route==='chat'){state.chatConv=cv.dataset.chatConv;loadChatMsgs(cv.dataset.chatConv);return}});
})();
